#include <iostream>
#include <sstream>
#include <string>
#include <vector>
using namespace std;

int main() {
    string qator;
    getline(cin, qator);

    vector<string> sozlar;
    istringstream ss(qator);
    string w;
    while (ss >> w) {
        sozlar.push_back(w);
    }

    for (size_t i = 0; i < sozlar.size(); i++) {
        if (i > 0) cout << ' ';
        cout << sozlar[sozlar.size() - 1 - i];
    }
    cout << endl;
    return 0;
}
